Proceso Buscar
  Dimension numeros[5] Como Entero;
  Para i <- 0 Hasta 4 Hacer
    numeros[i] <- (i + 1) * 7;
  FinPara
  Para Cada n En numeros Hacer
    Si n > 15 Entonces
      Escribir "Primero mayor que 15: ", n;
      Salir;
    FinSi
    Escribir "Reviso ", n;
  FinPara
FinProceso
